// <auto-generated/>
#nullable enable
// T-F529: a frozen copy of the ZIP reader as it was before T-F529 (main at 689c9759), kept only as
// ZipReaderOracleTests' oracle. Never changed: it is what the new reader is compared against.
using Archiver.Core.Services;
using Archiver.Core.Services.Zip;
using Archiver.Core.Services.Zip.Decryption;
using System.Collections.ObjectModel;
using System.IO.Compression;


namespace Archiver.Core.Tests.Services.Zip.Legacy;

/// <summary>
/// T-F234: one ZIP entry with the name Pakko uses for it everywhere (list, extract, test, scan) —
/// decoded by 7-Zip's rule, never <see cref="ZipArchiveEntry.FullName"/>, which .NET decodes as
/// UTF-8 for every entry without the UTF-8 flag.
/// </summary>
/// <param name="Entry">The .NET entry, for its data, sizes and CRC-32.</param>
/// <param name="FullName">The decoded name, '/'-separated.</param>
/// <param name="CollidesAfterDecoding">True when an earlier entry has different raw name bytes but
/// the same decoded name — writing both would silently lose one.</param>
/// <param name="ExtendedModifiedUtc">T-F298: the NTFS/extended-timestamp time, null when the entry
/// has none.</param>
internal sealed record LegacyNamedZipEntry(ZipArchiveEntry Entry, string FullName, bool CollidesAfterDecoding,
    DateTime? ExtendedModifiedUtc = null)
{
    /// <summary>T-F298: the time extraction gives the file or folder — the extended time, else the
    /// entry's DOS time.</summary>
    public DateTime ModifiedUtc => ExtendedModifiedUtc ?? Entry.LastWriteTime.UtcDateTime;
}

/// <summary>
/// T-F234: opens a ZIP for reading and pairs every <see cref="ZipArchiveEntry"/> with its decoded
/// name. Both lists come from the same central directory in the same order; a count mismatch means
/// the two readers disagree about the archive, which is reported as a corrupted archive rather than
/// falling back to .NET's UTF-8 names (that fallback is the bug this type exists to fix).
/// </summary>
internal sealed class LegacyZipArchiveReader : IDisposable
{
    public ZipArchive Archive { get; }
    public IReadOnlyList<LegacyNamedZipEntry> Entries { get; }

    private LegacyZipArchiveReader(ZipArchive archive, IReadOnlyList<LegacyNamedZipEntry> entries)
    {
        Archive = archive;
        Entries = entries;
    }

    // T-F513: the names are read first - their pass refuses an archive over ArchiveLimits.MaxEntries
    // before .NET's reader builds an object for every entry.
    public static LegacyZipArchiveReader Open(string path, ZipNameCodePages codePages)
    {
        List<(byte[] RawName, string Name, DateTime? ExtendedModifiedUtc)> names;
        using (FileStream raw = File.OpenRead(path))
        {
            // A device (NUL, a pipe) is no ZIP: .NET's reader said so too, as damaged data.
            if (!raw.CanSeek)
                throw new InvalidDataException("A ZIP archive is read from a file, not a device.");
            names = LegacyRawZipEntryLocator.ReadEntryNames(raw, codePages);
        }

        ZipArchive archive = ZipFile.OpenRead(path);
        try
        {
            if (names.Count != archive.Entries.Count)
                throw new InvalidDataException("ZIP central directory entry count mismatch while reading entry names.");

            return new LegacyZipArchiveReader(archive, Pair(archive.Entries, names));
        }
        catch
        {
            archive.Dispose();
            throw;
        }
    }

    private static List<LegacyNamedZipEntry> Pair(
        ReadOnlyCollection<ZipArchiveEntry> entries, List<(byte[] RawName, string Name, DateTime? ExtendedModifiedUtc)> names)
    {
        var firstRawByName = new Dictionary<string, byte[]>(StringComparer.Ordinal);
        var result = new List<LegacyNamedZipEntry>(entries.Count);
        for (int i = 0; i < entries.Count; i++)
        {
            (byte[]? rawName, string? name, DateTime? modifiedUtc) = names[i];
            bool collides = false;
            if (!name.EndsWith('/'))
            {
                if (firstRawByName.TryGetValue(name, out byte[]? firstRaw))
                    collides = !firstRaw.AsSpan().SequenceEqual(rawName);
                else
                    firstRawByName[name] = rawName;
            }
            result.Add(new LegacyNamedZipEntry(entries[i], name, collides, modifiedUtc));
        }
        return result;
    }

    public void Dispose() => Archive.Dispose();
}
